function UIMazeChooseBuffDialog:Awake()
    local pars = self.controller.Argument.parameters   --界面传参
    self.relics = pars.data
    if not self.relics then return end

    self:FillSelfCf()
    self:FillSelf()
end

function UIMazeChooseBuffDialog:FillSelfCf()
    SetButtonAction(self.btnClose, Bind(self, self.OnbtnClose))

    CfUtils.FillText(self.cfText1, localize("请选择一份情报"))
    CfUtils.FillText(self.cfText2, localize("稍后决定"))
end

function UIMazeChooseBuffDialog:FillSelf()
    for i = 1, #self.relics do
        local go = CfUtils.InstantiateGo(self.item, self.items)
        go.name = "relcis"..self.relics[i]

        local scr = CfUtils.GetLuaScr(go, UIMazeChooseBuffCellNode)
        if scr then
            local relicVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.relics[i], Constants.IDArea.Maze)
            scr:Refresh(relicVo, function(value)
                if value then
                    self.selectId = self.relics[i]
                end
            end, function()
                MazeMgr:GetInstance():MazeChooseRelic(self.relics[i], function()
                    self:OnbtnClose()
                end)
            end)
        end
    end
end

function UIMazeChooseBuffDialog:OnbtnClose()
    MazeMgr:GetInstance():RefeshMainUIAndPreview()
    UIModule.CloseDialog(self.controller)
end

